from __future__ import annotations
import json
import os
from pathlib import Path
from urllib.parse import quote

BASE=Path(__file__).resolve().parent
OUT=BASE/'dados'
RUN=BASE/'execucoes/2026-10-29'

def readjl(p):return [json.loads(x) for x in p.read_text(encoding='utf-8').splitlines() if x.strip()]
def relative(p):return quote(os.path.relpath(p,OUT).replace('\\','/'),safe='/')

if __name__=='__main__':
    docs={d['documento_id']:d for d in json.loads((RUN/'documentos.json').read_text(encoding='utf-8'))}
    report=json.loads((OUT/'relatorio.json').read_text(encoding='utf-8'))
    rows=[]
    for q in readjl(OUT/'questoes.jsonl'):
        d=docs[q['documento_id']];pages=q.get('paginas_pdf') or [1]
        images={int(p.stem.split('-')[-1]):p for p in (OUT/'fontes-visuais'/d['documento_id']).glob('pagina-*.png')}
        rows.append({'tipo':'Questão','id':q['ocorrencia_id'],'banca':d['banca'],'concurso':d['concurso'],'titulo':d['titulo'],'numero':q['numero_original'],'disciplina':q.get('disciplina_original') or '', 'texto':q['enunciado_original'],'contextos':[x.get('texto','') for x in q.get('contextos',[])], 'alternativas':q.get('alternativas',[]),'habilidades':[x.get('descricao_operacional','') for x in q.get('habilidades',[])],'assuntos':[x.get('assunto','') for x in q.get('classificacoes',[])],'formato':q.get('formato'),'status':q['status_extracao'],'alertas':q.get('alertas',[]),'gabaritos':[dict(g,pdf=relative(docs[g['documento_id']]['arquivo'])+'#page='+str(g['paginas_pdf'][0])) for g in q.get('gabaritos',[])],'gabarito_divergente':q.get('gabarito_divergente',False),'pdf':relative(d['arquivo'])+'#page='+str(pages[0]),'paginas':pages,'imagens':[relative(images[p]) for p in pages if p in images]})
    for t in readjl(OUT/'topicos.jsonl'):
        d=docs[t['documento_id']];pages=t.get('paginas_pdf') or [1]
        rows.append({'tipo':'Tópico','id':t['topico_id'],'banca':d['banca'],'concurso':d['concurso'],'titulo':d['titulo'],'numero':t.get('numero_original') or '', 'disciplina':t.get('disciplina_original') or '', 'texto':t['texto_original'],'caminho':t.get('caminho_original',[]),'escopo':t.get('escopo_cargos',[]),'especialidades':t.get('escopo_especialidades',[]),'status':t.get('status_extracao'),'alertas':t.get('alertas',[]),'pdf':relative(d['arquivo'])+'#page='+str(pages[0]),'paginas':pages,'derivado':t.get('unidade_indexacao_derivada',False)})
    data=json.dumps(rows,ensure_ascii=False).replace('<','\\u003c')
    page=r'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Base de questões e editais</title><style>body{margin:0;background:#f4f6f8;color:#1b3148;font:16px/1.55 system-ui,sans-serif}main{max-width:1150px;margin:auto;padding:28px}h1{margin-bottom:4px}a{color:#075aa6}header p{margin-top:4px;color:#496178}.filters{display:flex;flex-wrap:wrap;gap:10px;margin:24px 0}input,select,button{font:inherit;padding:9px 11px;border:1px solid #bac8d5;border-radius:6px;background:white}input{flex:1;min-width:240px}article{background:white;border:1px solid #d6e0e8;border-radius:8px;padding:22px;margin:18px 0}article h2{font-size:18px;margin:0 0 12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}summary{cursor:pointer;color:#075aa6}.meta{color:#52687d;font-size:14px}.alert{color:#805112;background:#fff6de;padding:8px}.tags{color:#365c48}img{max-width:100%;height:auto;border:1px solid #ccd6df;margin-top:10px}.nav{display:flex;gap:15px;align-items:center;margin:20px 0}li{margin-bottom:6px}</style><main><header><h1>Base de questões e editais</h1><p id="stats"></p><p><a href="conteudo.sqlite">Base SQLite</a> · <a href="questoes.jsonl">Questões JSONL</a> · <a href="questoes.csv">Questões CSV</a> · <a href="topicos.jsonl">Tópicos JSONL</a> · <a href="relatorio.json">Auditoria</a> · <a href="../README.md">Guia</a></p><p class="meta">Classificações automáticas são candidatas. Gabaritos mantêm a natureza da publicação e o histórico; divergências ficam visíveis. Elementos gráficos podem ser conferidos na página original.</p></header><div class="filters"><input id="busca" type="search" placeholder="Buscar conceito, expressão, habilidade ou cargo" aria-label="Buscar"><select id="tipo" aria-label="Tipo"><option value="">Questões e tópicos</option><option>Questão</option><option>Tópico</option></select><select id="banca" aria-label="Banca"><option value="">Todas as bancas</option></select><select id="concurso" aria-label="Concurso"><option value="">Todos os concursos</option></select><select id="qualidade" aria-label="Qualidade"><option value="">Todos os estados</option><option value="extraido">Extraídos</option><option value="precisa_revisao">Precisam de revisão</option></select></div><div id="contador" class="meta"></div><div class="nav"><button id="anterior">Anterior</button><span id="pagina"></span><button id="proxima">Próxima</button></div><div id="resultados"></div><script type="application/json" id="dados">DATA_PLACEHOLDER</script><script>
const D=JSON.parse(document.getElementById('dados').textContent),S=REPORT_PLACEHOLDER;
const $=id=>document.getElementById(id),norm=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,' ');
$('stats').textContent=`${S.ocorrencias_questoes} ocorrências em ${S.provas} cadernos; ${S.questoes_unicas} conteúdos únicos; ${S.topicos} registros de tópicos.`;
for(const field of ['banca','concurso'])for(const value of [...new Set(D.map(r=>r[field]))].sort()){const o=document.createElement('option');o.value=value;o.textContent=value;$(field).append(o)}
for(const r of D)r.search=norm([r.banca,r.concurso,r.titulo,r.disciplina,r.texto,...(r.contextos||[]),...(r.alternativas||[]).map(a=>a.texto),...(r.habilidades||[]),...(r.assuntos||[]),...(r.caminho||[]),...(r.escopo||[]),...(r.especialidades||[]),r.numero,r.formato,r.id].join(' '));
let found=D,index=0;const size=25;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function details(title,content){const d=el('details');d.append(el('summary',title));d.append(content);return d}
function render(){const target=$('resultados');target.replaceChildren();$('contador').textContent=found.length+' resultados';$('pagina').textContent=`Página ${index+1} de ${Math.max(1,Math.ceil(found.length/size))}`;$('anterior').disabled=index===0;$('proxima').disabled=(index+1)*size>=found.length;
 for(const r of found.slice(index*size,(index+1)*size)){const a=el('article');a.append(el('h2',`${r.tipo} ${r.numero} · ${r.titulo}`));a.append(el('p',`${r.banca} · ${r.disciplina||'Disciplina não identificada'} · ${r.status||'estado não informado'} · página(s) ${r.paginas.join(', ')}`,'meta'));if(r.alertas?.length)a.append(el('p',r.alertas.join(' · '),'alert'));if(r.contextos?.length)a.append(details('Contexto e texto-base',el('pre',r.contextos.join('\n\n'))));a.append(el('pre',r.texto));if(r.alternativas?.length){const list=el('div');for(const alt of r.alternativas)list.append(el('p',`${alt.rotulo}) ${alt.texto}`));a.append(list)}if(r.habilidades?.length)a.append(details('Habilidades candidatas',el('pre',r.habilidades.join('\n'))));if(r.assuntos?.length)a.append(el('p','Assuntos candidatos: '+r.assuntos.join(' · '),'tags'));if(r.escopo?.length)a.append(details('Cargos e especialidades',el('pre',[...r.escopo,...(r.especialidades||[])].join('\n'))));if(r.derivado)a.append(el('p','Unidade de indexação derivada do tópico original.','meta'));if(r.gabarito_divergente)a.append(el('p','Gabaritos divergentes: resposta de referência não confirmada.','alert'));if(r.gabaritos?.length){const hist=el('div');for(const g of r.gabaritos){const item=el('p',`${g.resposta} · ${g.situacao} · ${g.natureza} · `);const link=el('a','Abrir publicação do gabarito');link.href=g.pdf;link.target='_blank';item.append(link);hist.append(item)}a.append(details('Consultar gabarito e histórico',hist))}const source=el('a','Abrir PDF original');source.href=r.pdf;source.target='_blank';a.append(source);if(r.imagens?.length){const wrap=el('div');for(const src of r.imagens){const img=el('img');img.src=src;img.loading='lazy';img.alt='Página original da questão';wrap.append(img)}a.append(details('Conferir página original como imagem',wrap))}a.append(el('p',r.id,'meta'));target.append(a)}
}
function filter(){const terms=(norm($('busca').value).match(/"[^"]+"|\S+/g)||[]).map(t=>t.replace(/^"|"$/g,''));found=D.filter(r=>(!$('tipo').value||r.tipo===$('tipo').value)&&(!$('banca').value||r.banca===$('banca').value)&&(!$('concurso').value||r.concurso===$('concurso').value)&&(!$('qualidade').value||r.status===$('qualidade').value)&&terms.every(t=>r.search.includes(t)));index=0;render()}
for(const id of ['busca','tipo','banca','concurso','qualidade'])$(id).addEventListener('input',filter);$('anterior').onclick=()=>{if(index>0){index--;render()}};$('proxima').onclick=()=>{if((index+1)*size<found.length){index++;render()}};render();
</script></main></html>'''
    page=page.replace('DATA_PLACEHOLDER',data).replace('REPORT_PLACEHOLDER',json.dumps(report,ensure_ascii=False).replace('<','\\u003c'))
    (OUT/'index.html').write_text(page,encoding='utf-8')
    print(json.dumps({'questoes_e_topicos':len(rows),'indice':str(OUT/'index.html')}))
